  "Auto makes the CDSs that share a locus identifier one unit and every other CDS a unit of its own. CDS makes each CDS a unit. Locus makes each locus a unit and requires a locus identifier, such as /locus_tag, on every CDS.": "Automatycznie: sekwencje CDS o wspólnym identyfikatorze locus tworzą jedną jednostkę, a każda inna sekwencja CDS – osobną jednostkę. CDS: każda sekwencja CDS jest jednostką. Locus: każdy locus jest jednostką; wymaga identyfikatora locus, takiego jak /locus_tag, przy każdej sekwencji CDS.",
  "Auto shows these fields throughout the diagram": "Opcja Automatycznie pokazuje te pola w całym diagramie",
  "Auto will hide these fields throughout the diagram on the next successful Generate": "Opcja Automatycznie ukryje te pola w całym diagramie przy następnym udanym generowaniu",
  "Auto will show these fields throughout the diagram on the next successful Generate": "Opcja Automatycznie pokaże te pola w całym diagramie przy następnym udanym generowaniu",
