  "Base colors for features, comparison tracks, and collinear blocks. The selected palette supplies unchanged colors; colors you edit override it; when you change the palette, a dialog asks whether to keep them.": "Kolory bazowe cech, ścieżek porównania i bloków kolinearnych. Kolory, których nie zmieniono ręcznie, pochodzą z wybranej palety; kolory zmienione ręcznie zastępują odpowiadające im kolory palety. Po zmianie palety okno dialogowe pyta, czy zachować ręcznie zmienione kolory.",
  "Base text shown in the diagram legend. Leave blank to use the auto label shown here; two-color tracks add (+) and (-).": "Tekst podstawowy wyświetlany w legendzie diagramu. Pozostaw puste, aby użyć etykiety automatycznej widocznej tutaj; ścieżki dwukolorowe dodają (+) i (-).",
