  "Halo": "Halo",
  "Halo draws a white outline around the letters of each label with a leader, so leaders behind them are cut away. Box draws a white box behind the letters. None draws neither.": "Opcja Halo rysuje biały kontur wokół liter każdej etykiety z linią wiodącą, dzięki czemu linie wiodące za nimi są wycięte. Opcja Ramka rysuje białe pole za literami. Opcja Brak nie rysuje żadnego z nich.",
  "Hatch": "Kreskowanie",
  "Head Length Ratio": "Stosunek długości grotu",
  "Head length and shaft width apply to Arrow features and remain available even when no feature currently uses that rendering.": "Długość grotu i szerokość trzonu dotyczą cech renderowanych jako Strzałka i pozostają dostępne, nawet gdy żadna cecha nie używa obecnie tego renderowania.",
  "Head length divided by the full rendered feature thickness. Leave blank for Auto. Auto starts from the mode-specific default and lengthens the head as the shaft narrows.": "Długość grotu podzielona przez pełną wyrenderowaną grubość cechy. Pozostaw puste, aby użyć wartości automatycznej. Wartość automatyczna jest liczona od wartości domyślnej dla danego trybu i wydłuża grot, gdy trzon się zwęża.",
  "Height": "Wysokość",
  "Height must be a positive number of pixels (px optional).": "Wysokość musi być dodatnią liczbą pikseli (px opcjonalnie).",
  "Height of the feature blocks.": "Wysokość bloków cech.",
  "Height of the linear GC content and GC skew tracks. Applies to whichever of those tracks are enabled when the diagram is generated.": "Wysokość ścieżek zawartości GC i GC skew w diagramie liniowym. Dotyczy tych ścieżek, które są włączone podczas generowania diagramu.",
  "Height of this linear depth coverage track in px. Leave blank for auto.": "Wysokość tej ścieżki głębokości pokrycia diagramu liniowego w px. Pozostaw puste, aby użyć wartości automatycznej.",
