  "Legend: entries {items} repeat an earlier entry of their list and were dropped.": {"few": "Legenda: wpisy {items} powtarzają wcześniejszy wpis swojej listy i zostały odrzucone.", "many": "Legenda: wpisy {items} powtarzają wcześniejszy wpis swojej listy i zostały odrzucone.", "other": "Legenda: wpisy {items} powtarzają wcześniejszy wpis swojej listy i zostały odrzucone."},
  "Legend: entry {items} had a color the app does not accept and was dropped.": "Legenda: wpis {items} miał kolor, którego aplikacja nie akceptuje, i został odrzucony.",
  "Legend: entry {items} repeats an earlier entry of its list and was dropped.": "Legenda: wpis {items} powtarza wcześniejszy wpis swojej listy i został odrzucony.",
  "Legend: the color edit stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an edit of its own; that edit is used and this one was dropped.": "Legenda: edycja koloru zapisana pod „{label}” ({path}) przechodzi do wiersza „{used}”, który ma własną edycję; użyto tamtej edycji, a ta została odrzucona.",
  "Legend: the color edit stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "Legenda: edycja koloru zapisana pod „{label}” ({path}) określa wiersz „{used}”, który określa też późniejsza edycja; użyto późniejszej edycji, a ta została odrzucona.",
  "Legend: the entry stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an entry of its own; that entry is used and this one was dropped.": "Legenda: wpis zapisany pod „{label}” ({path}) przechodzi do wiersza „{used}”, który ma własny wpis; użyto tamtego wpisu, a ten został odrzucony.",
  "Legend: the entry stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "Legenda: wpis zapisany pod „{label}” ({path}) określa wiersz „{used}”, który określa też późniejsza edycja; użyto późniejszej edycji, a ten wpis został odrzucony.",
  "Legend: the position \"{stored}\" ({path}) is not one of its mode's positions; it is not used.": "Legenda: pozycja „{stored}” ({path}) nie jest dostępna w tym trybie; nie jest używana.",
  "Legend: the position \"{stored}\" ({path}) is not one of its mode's positions; {used} is used.": "Legenda: pozycja „{stored}” ({path}) nie jest dostępna w tym trybie; użyto: {used}.",
  "Legend: the stroke edit stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an edit of its own; that edit is used and this one was dropped.": "Legenda: edycja konturu zapisana pod „{label}” ({path}) przechodzi do wiersza „{used}”, który ma własną edycję; użyto tamtej edycji, a ta została odrzucona.",
  "Legend: the stroke edit stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "Legenda: edycja konturu zapisana pod „{label}” ({path}) określa wiersz „{used}”, który określa też późniejsza edycja; użyto późniejszej edycji, a ta została odrzucona.",
