  "Linear vertical spacing after the track, in pixels (px optional; nonnegative). Leave blank for the automatic spacing.": "Pionowy rozstaw za ścieżką diagramu liniowego w pikselach (px opcjonalnie; nieujemny). Pozostaw puste, aby użyć rozstawu automatycznego.",
  "Link Linear scale and ruler label font sizes": "Połącz rozmiary czcionki skali i etykiet linijki diagramu liniowego",
  "Link Scale and Ruler Label Font Sizes": "Połącz rozmiary czcionki skali i etykiet linijki",
  "List all 12 standard BLAST outfmt 6 fields in the \"# Fields:\" line, or remove the line so that the first 12 columns are read in the standard order.": "Wymień wszystkie 12 standardowych pól BLAST outfmt 6 w wierszu „# Fields:” albo usuń ten wiersz, aby pierwsze 12 kolumn zostało odczytanych w standardowej kolejności.",
  "Live edit": "Edycja na żywo",
  "Live edit applying: geometry is being updated. Direct edits already applied are kept.": "Trwa stosowanie edycji na żywo: geometria jest aktualizowana. Już zastosowane edycje bezpośrednie zostają zachowane.",
  "Live edit failed: direct edits already applied are kept; geometry may still need updating.": "Edycja na żywo nie powiodła się: zastosowane już edycje bezpośrednie zostały zachowane; geometria może nadal wymagać aktualizacji.",
  "Live edit. Showing a track applies on Generate if the Result did not draw it when its Session was loaded; after a Depth file or series change, or a change of the records the Depth files map to; for a custom stack row added since the last Generate or a stack the last Generate could not build; and, with a Circular custom track stack or Circular track widths or radii, for Hide GC Content and Hide GC Skew turned off": "Edycja na żywo. Pokazanie ścieżki stosuje się przy generowaniu, jeśli wynik nie narysował jej w chwili wczytania sesji; po zmianie pliku lub serii głębokości albo rekordów, do których przypisano pliki głębokości; dla wiersza niestandardowego stosu dodanego od ostatniego generowania lub stosu, którego ostatnie generowanie nie mogło zbudować; a także, przy niestandardowym stosie ścieżek diagramu kolistego albo szerokościach lub promieniach ścieżek diagramu kolistego, po wyłączeniu opcji Ukryj zawartość GC i Ukryj GC skew",
  "Live edit: feature color, label text, and visibility update the current Result; geometry may rerender automatically.": "Edycja na żywo: kolor cechy, tekst etykiety i widoczność aktualizują bieżący wynik; geometria może zostać przerysowana automatycznie.",
  "Live edit: legend text, order, stroke, and removal update the current Result.": "Edycja na żywo: tekst legendy, kolejność, kontur i usunięcie aktualizują bieżący wynik.",
  "Live edit; the position applies on Generate after the Multi-Record Canvas change": "Edycja na żywo; pozycja jest stosowana przy generowaniu po zmianie ustawienia Płótno wielu rekordów",
