  "Load with {substitutes}: the Session opens and its text is drawn in {substitutes}, the nearest available fonts.": {"few": "Wczytaj z użyciem {substitutes}: sesja się otwiera, a jej tekst jest rysowany czcionkami {substitutes}, czyli najbliższymi dostępnymi.", "many": "Wczytaj z użyciem {substitutes}: sesja się otwiera, a jej tekst jest rysowany czcionkami {substitutes}, czyli najbliższymi dostępnymi.", "other": "Wczytaj z użyciem {substitutes}: sesja się otwiera, a jej tekst jest rysowany czcionkami {substitutes}, czyli najbliższymi dostępnymi."},
