  "Main": "Główny",
  "Manual order and row assignment for multi-record canvas. Use Up/Down for left-to-right order within each row.": "Ręczna kolejność i przypisanie do wierszy na płótnie wielu rekordów. Użyj przycisków W górę / W dół, aby ustawić kolejność od lewej do prawej w każdym wierszu.",
  "Manual scale interval for circular mode (in bp; must be > 0). Overrides automatic calculation.": "Ręczny interwał skali dla diagramu kolistego (w bp; musi być > 0). Nadpisuje obliczenia automatyczne.",
  "Manual tick interval for Ruler scale style in bp (must be > 0). Leave blank to calculate automatically.": "Ręczny interwał znaczników dla stylu skali Linijka w bp (musi być > 0). Pozostaw puste, aby obliczyć automatycznie.",
  "Marks": "Oznaczenia",
  "Match depth references to the selected record.": "Dopasuj sekwencje referencyjne w TSV głębokości do wybranego rekordu.",
  "Match height": "Wysokość dopasowania",
