  "Max hits per protein for groups": "Maks. liczba trafień na białko dla grup",
  "Max target seqs": "Maksymalna liczba sekwencji docelowych",
  "Max unit gap": "Maks. odstęp w jednostkach",
  "Maximum GC percentage for percent-mode clipping and axis scaling.": "Maksymalny procent GC do ograniczania wartości i skalowania osi w trybie procentowym.",
  "Maximum depth for clipping and normalization. Leave blank for auto.": "Maksymalna głębokość do ograniczania i normalizacji. Pozostaw puste, aby użyć wartości automatycznej.",
  "Maximum distinct subject proteins, not counting the protein itself, kept per query protein in each directed record-pair search to construct Similarity groups and Collinear blocks after result filtering. Leave blank to keep all hits passing the result filters. This does not limit raw LOSATP candidates or Pairwise display matches.": "Maksymalna liczba różnych białek subject, nie licząc samego białka, zachowywana dla jednego białka query w każdym skierowanym wyszukiwaniu pary rekordów do budowy grup podobieństwa i bloków kolinearnych po filtrowaniu wyników. Pozostaw puste, aby zachować wszystkie trafienia przechodzące filtry wyników. Nie ogranicza to surowych kandydatów LOSATP ani dopasowań w trybie Dopasowania parami.",
  "Maximum filtered matches displayed per query protein in Pairwise mode. This does not limit LOSATP candidates or Similarity/Collinear member evidence.": "Maksymalna liczba przefiltrowanych dopasowań wyświetlanych dla jednego białka query w trybie Dopasowania parami. Nie ogranicza kandydatów LOSATP ani dowodów dla członków grup podobieństwa i bloków kolinearnych.",
  "Maximum number of units (loci, or CDSs without a locus identifier; see Unit mode) between neighboring anchors of one block, on both records. 0 joins adjacent units only. With Diagonal drift 0, a gap is bridged only when both records skip the same number of units.": "Maksymalna liczba jednostek (loci lub CDS bez identyfikatora locus; zobacz Tryb jednostek) między sąsiednimi kotwicami jednego bloku, w obu rekordach. 0 łączy tylko sąsiednie jednostki. Przy wartości Dryf ukośny równej 0 odstęp jest pokonywany tylko wtedy, gdy oba rekordy pomijają taką samą liczbę jednostek.",
  "Members": "Członkowie",
