  "Minimum depth for clipping and normalization. Leave blank for auto.": "Minimalna głębokość do ograniczania i normalizacji. Pozostaw puste, aby użyć wartości automatycznej.",
  "Minimum label-to-label vertical spacing for circular layouts in px.": "Minimalny pionowy rozstaw między etykietami w układach diagramu kolistego, w px.",
  "Minimum radius ratio": "Minimalny stosunek promienia",
  "Minimum reserved height for the measured feature band, in pixels (px optional; positive). The actual reservation is max(measured, configured); this does not change feature glyph thickness, which is controlled by Feature Height (--feature_height). Auto values vary by record.": "Minimalna zarezerwowana wysokość zmierzonego pasa cech w pikselach (px opcjonalnie; dodatnia). Faktyczna rezerwacja to max(zmierzona, skonfigurowana); nie zmienia to grubości symbolu cechy, którą określa Wysokość cechy (--feature_height). Wartości automatyczne różnią się między rekordami.",
