  "Move the track, reduce widths, disable conflicting labels, or place it on the other side of the Axis.": "Przenieś ścieżkę, zmniejsz szerokości, wyłącz kolidujące etykiety albo umieść ją po drugiej stronie osi.",
  "Move up within side": "Przenieś w górę w obrębie strony",
  "Multi-Record Canvas": "Płótno wielu rekordów",
  "Multi-Record Canvas uses a grid. Turn it off to select one record.": "Płótno wielu rekordów używa siatki. Wyłącz tę opcję, aby zaznaczyć jeden rekord.",
  "Name": "Nazwa",
  "Name / Species": "Nazwa / gatunek",
  "Name of the Depth series this row draws. Typing renames the series everywhere: its series card, every row that draws it, and the legend. Leave blank for the default name: Depth, or Depth N when there are several series.": "Nazwa serii głębokości rysowanej przez ten wiersz. Wpisanie nazwy zmienia ją wszędzie: w karcie serii, w każdym wierszu rysującym tę serię i w legendzie. Pozostaw puste, aby użyć nazwy domyślnej: Depth lub Depth N, gdy serii jest kilka.",
  "Name of the Depth series this row draws. Typing renames the series everywhere: its series card, every row that draws it, and the legend. The legend lists series in custom-stack order and omits series that no enabled row draws. Leave blank for the default name: Depth, or Depth N when there are several series.": "Nazwa serii głębokości rysowanej przez ten wiersz. Wpisanie nazwy zmienia ją wszędzie: w karcie serii, w każdym wierszu rysującym tę serię i w legendzie. Legenda wymienia serie w kolejności niestandardowego stosu i pomija serie, których nie rysuje żaden włączony wiersz. Pozostaw puste, aby użyć nazwy domyślnej: Depth lub Depth N, gdy serii jest kilka.",
  "Name of this Depth series in the legend. The legend label field of every Depth row that draws this series edits the same name. Leave blank for the default name: Depth, or Depth N when there are several series.": "Nazwa tej serii głębokości w legendzie. Pole etykiety legendy w każdym wierszu głębokości rysującym tę serię edytuje tę samą nazwę. Pozostaw puste, aby użyć nazwy domyślnej: Depth lub Depth N, gdy serii jest kilka.",
