  "Raw LOSATP search limit per query protein (--max-target-seqs). In a within-record search the query protein itself counts as one target. Leave blank for an unbounded search, the default. Changing this value requires matching raw search results. Each mode remembers its own hit limits.": "Limit surowego wyszukiwania LOSATP na białko query (--max-target-seqs). W wyszukiwaniu w obrębie rekordu samo białko query liczy się jako jeden cel. Pozostaw puste, aby wyszukiwać bez limitu (domyślnie). Zmiana tej wartości wymaga pasujących surowych wyników wyszukiwania. Każdy tryb zapamiętuje własne limity trafień.",
