  "Reverses {records} so all {count} chosen features point left.": {"few": "Odwraca {records}, aby wszystkie wybrane cechy ({count}) były skierowane w lewo.", "many": "Odwraca {records}, aby wszystkie wybrane cechy ({count}) były skierowane w lewo.", "other": "Odwraca {records}, aby wszystkie wybrane cechy ({count}) były skierowane w lewo."},
  "Reverses {records} so all {count} chosen features point right.": {"few": "Odwraca {records}, aby wszystkie wybrane cechy ({count}) były skierowane w prawo.", "many": "Odwraca {records}, aby wszystkie wybrane cechy ({count}) były skierowane w prawo.", "other": "Odwraca {records}, aby wszystkie wybrane cechy ({count}) były skierowane w prawo."},
  "Reverses {records} so the chosen feature points left.": "Odwraca {records}, aby wybrana cecha była skierowana w lewo.",
