  "Reverses {records}.": "Odwraca {records}.",
  "Reversing flips a whole record with its labels and ribbons. Strands in the data (+/−) do not change.": "Odwrócenie zmienia kierunek całego rekordu wraz z jego etykietami i wstążkami. Nici w danych (+/−) nie zmieniają się.",
