  "Rotate linear labels in degrees (e.g., 45). In Above Feature mode, rotated labels start from each feature midpoint.": "Obróć etykiety diagramu liniowego o podaną liczbę stopni (np. 45). W trybie Nad cechą obrócone etykiety zaczynają się w punkcie środkowym każdej cechy.",
  "Rotate record to feature": "Obróć rekord do cechy",
  "Rotate record to feature on Generate": "Obróć rekord do cechy przy generowaniu",
  "Rotate record using this feature": "Obróć rekord według tej cechy",
  "Row Gap Ratio": "Stosunek odstępu wierszy",
  "Row actions": "Akcje wiersza",
  "Row actions for {id}": "Akcje wiersza dla {id}",
  "Row for {record}": "Wiersz dla rekordu {record}",
  "Row gap ratio": "Stosunek odstępu wierszy",
  "Rows above Axis are outside the circular axis; rows below Axis are inside it. Arrow buttons reorder within the current side only. Use Move outside Axis or Move inside Axis to cross the Axis.": "Wiersze nad wierszem Oś leżą na zewnątrz osi diagramu kolistego, a wiersze pod wierszem Oś – wewnątrz niej. Przyciski strzałek zmieniają kolejność tylko w obrębie bieżącej strony. Użyj polecenia Przenieś na zewnątrz osi lub Przenieś do wnętrza osi, aby przekroczyć oś.",
  "Rows before Axis render above it; rows after Axis render below it. A Depth slot selects one global series and does not control vertical order. A record without a Depth TSV for that series does not draw it, but its space in the stack stays reserved.": "Wiersze przed wierszem Oś są rysowane nad osią; wiersze po wierszu Oś – pod osią. Slot głębokości wybiera jedną serię globalną i nie steruje kolejnością pionową. Jeśli rekord nie ma TSV głębokości dla tej serii, seria nie jest dla niego rysowana, ale jej miejsce w stosie pozostaje zarezerwowane.",
  "Rows {upper}–{lower}": "Wiersze {upper}–{lower}",
  "Rule error": "Błąd reguły",
  "Ruler (Ticks)": "Linijka (znaczniki)",
  "Ruler Label Color": "Kolor etykiet linijki",
  "Ruler Label Font Size": "Rozmiar czcionki etykiet linijki",
  "Ruler label color": "Kolor etykiet linijki",
  "Ruler on Axis": "Linijka na osi",
  "Rules are evaluated from top to bottom. Off hides the feature and leaves it out of protein search; Leave out of protein search keeps its visibility and leaves it out of protein search.": "Reguły są oceniane od góry do dołu. Opcja Wyłączone ukrywa cechę i wyklucza ją z wyszukiwania białek; opcja Wyklucz z wyszukiwania białek zachowuje jej widoczność i wyklucza ją z wyszukiwania białek.",
  "Rules on the same qualifier: the first match wins.": "Reguły dla tego samego kwalifikatora: wygrywa pierwsze dopasowanie.",
  "Run LOSAT": "Uruchom LOSAT",
  "Run LOSAT for all adjacent pairs": "Uruchom LOSAT dla wszystkich sąsiednich par",
  "Run LOSAT requires at least 2 loaded sequences.": "Aby użyć opcji Uruchom LOSAT, wczytaj co najmniej 2 sekwencje.",
  "Run info": "Informacje o uruchomieniu",
  "Run info is available after a successful manual generation.": "Informacje o uruchomieniu są dostępne po pomyślnym ręcznym wygenerowaniu.",
  "Run time": "Czas działania",
  "Running LOSAT: {completed}/{total} source jobs complete": "Uruchamianie LOSAT: ukończone zadania źródeł: {completed}/{total}",
  "Running {program} comparisons for the circular diagram: {completed}/{total} jobs complete": "Uruchamianie porównań {program} dla diagramu kolistego: ukończone zadania: {completed}/{total}",
  "SPECIFIC RULES": "REGUŁY SZCZEGÓŁOWE",
  "SVG ID": "ID SVG",
  "SVG and Interactive SVG exports carry the characters they use of this font, so they show it on computers without it. Fonts whose license forbids embedding are not embedded. Turned off, the SVG files keep only the font name. PNG export always draws this font, whatever this setting and the font's license. PDF export embeds this font whatever this setting; a font whose license forbids embedding is drawn in the nearest Liberation font.": "Eksporty SVG i Interaktywny SVG zawierają użyte znaki tej czcionki, dzięki czemu wyświetlają ją na komputerach, które jej nie mają. Czcionki, których licencja zabrania osadzania, nie są osadzane. Po wyłączeniu pliki SVG zachowują tylko nazwę czcionki. Eksport PNG zawsze rysuje tę czcionkę, niezależnie od tego ustawienia i licencji czcionki. Eksport PDF osadza tę czcionkę niezależnie od tego ustawienia; czcionka, której licencja zabrania osadzania, jest rysowana najbliższą czcionką Liberation.",
  "SVG export error": "Błąd eksportu SVG",
  "Safe ({count})": "Bezpieczne ({count})",
  "Safe diagnostics": "Bezpieczna diagnostyka",
  "Same orientation": "Ta sama orientacja",
  "Satoshi Kawato": "Satoshi Kawato",
  "Save": "Zapisz",
  "Save Raw LOSAT TSV": "Zapisz surowy LOSAT TSV",
  "Save Raw LOSAT TSV for #{from} to #{to}": "Zapisz surowy LOSAT TSV dla porównania z #{from} do #{to}",
  "Save Session": "Zapisz sesję",
  "Save Session afterwards writes the current format. The file itself is not changed.": "Późniejsze zapisanie sesji zapisze ją w bieżącym formacie. Sam plik nie zostanie zmieniony.",
  "Save Session needs current feature metadata for the loaded Result. Generate once, then Save Session.": "Przycisk Zapisz sesję wymaga aktualnych metadanych cech dla wczytanego wyniku. Wygeneruj raz, a potem kliknij Zapisz sesję.",
  "Save Session stores the current Result and settings draft. The SVG, Interactive SVG, PNG, and PDF buttons download the current Result. Neither applies pending settings.": "Przycisk Zapisz sesję zapisuje bieżący wynik i wersję roboczą ustawień. Przyciski SVG, Interaktywny SVG, PNG i PDF pobierają bieżący wynik. Żaden z nich nie stosuje oczekujących ustawień.",
  "Save stores the current Result and generation settings draft. It does not Generate.": "Przycisk Zapisz sesję przechowuje bieżący wynik i wersję roboczą ustawień generowania. Nie uruchamia generowania.",
  "Save the current Result and settings draft without generating": "Zapisz bieżący wynik i wersję roboczą ustawień bez generowania",
  "Saved Circular diagram: its settings ({path}) could not be read; that diagram and its Results are left out.": "Zapisany diagram kolisty: nie udało się odczytać jego ustawień ({path}); ten diagram i jego wyniki zostały pominięte.",
  "Saved Linear diagram: its settings ({path}) could not be read; that diagram and its Results are left out.": "Zapisany diagram liniowy: nie udało się odczytać jego ustawień ({path}); ten diagram i jego wyniki zostały pominięte.",
  "Saved alignment needs repair.": "Zapisane wyrównanie wymaga naprawy.",
  "Saved comparison needs a decision": "Zapisane porównanie wymaga decyzji",
  "Saved comparison preserved as read-only": "Zapisane porównanie zachowane tylko do odczytu",
  "Saved diagram: the settings of the saved diagram ({path}) could not be read. The file loads as settings only; the saved Results, the GenBank, GFF and FASTA inputs, the feature list and the caches are left out.": "Zapisany diagram: nie udało się odczytać ustawień zapisanego diagramu ({path}). Plik wczytuje się tylko jako ustawienia; zapisane wyniki, dane wejściowe GenBank, GFF i FASTA, lista cech oraz pamięci podręczne zostały pominięte.",
  "Saved names waiting for their original members: {names}": "Zapisane nazwy oczekujące na pierwotnych członków grup: {names}",
  "Saved other diagram: its settings ({path}) could not be read; that diagram and its Results are left out.": "Zapisany inny diagram: nie udało się odczytać jego ustawień ({path}); ten diagram i jego wyniki zostały pominięte.",
  "Saving session. Retry after saving finishes.": "Trwa zapisywanie sesji. Spróbuj ponownie po zakończeniu.",
  "Saving session…": "Zapisywanie sesji…",
