  "Search similarity groups...": "Szukaj grup podobieństwa…",
  "Search with a JavaScript regular expression; upper and lower case match alike.": "Wyszukiwanie wyrażeniem regularnym JavaScript; wielkość liter nie ma znaczenia.",
  "Select Hide GC Content, or reduce GC Content Width (with Custom Track Slots on, the row width).": "Zaznacz Ukryj zawartość GC albo zmniejsz Szerokość ścieżki zawartości GC (przy włączonych niestandardowych slotach ścieżek: szerokość wiersza).",
  "Select Hide GC Skew, or reduce GC Skew Width (with Custom Track Slots on, the row width).": "Zaznacz Ukryj GC skew albo zmniejsz Szerokość ścieżki GC skew (przy włączonych niestandardowych slotach ścieżek: szerokość wiersza).",
