  "Select an eligible enabled anchor for an annotation track whose placement is Overlay anchor (Circular) or On axis (Linear).": "Zaznacz kwalifikującą się, włączoną kotwicę dla ścieżki adnotacji z rozmieszczeniem Kotwica nakładki (diagram kolisty) lub Na osi (diagram liniowy).",
