  "Select one eligible enabled feature track as the axis.": "Zaznacz jedną kwalifikującą się, włączoną ścieżkę cech jako oś.",
  "Select one record to edit crop, orientation, and title lines.": "Zaznacz jeden rekord, aby edytować przycięcie, orientację i wiersze tytułu.",
  "Select preset...": "Zaznacz ustawienie wstępne…",
  "Select target record": "Zaznacz rekord docelowy",
  "Select the record to draw as one Circular diagram. Leave this on All records to draw each record as its own diagram.": "Zaznacz rekord, który ma zostać narysowany jako jeden diagram kolisty. Pozostaw opcję Wszystkie rekordy, aby narysować każdy rekord jako osobny diagram.",
  "Select which feature types to draw.": "Zaznacz typy cech do narysowania.",
  "Select {label}, {coordinates} for {record}": "Zaznacz cechę {label}, {coordinates} dla rekordu {record}",
  "Select {label}, {coordinates}, strand {strand} for {record}": "Zaznacz cechę {label}, {coordinates}, nić {strand} dla rekordu {record}",
  "Selected LOSAT comparisons require LOSATP Pairwise mode. For Similarity groups or Collinear blocks, choose Run LOSAT for all adjacent pairs.": "Wybrane porównania LOSAT wymagają trybu Dopasowania parami w LOSATP. Dla grup podobieństwa lub bloków kolinearnych wybierz Uruchom LOSAT dla wszystkich sąsiednich par.",
