  "Selected pairs": "Wybrane pary",
  "Selected pairs ({count})": "Wybrane pary ({count})",
  "Selected record was not found in the current file. Choose another record.": "Nie znaleziono wybranego rekordu w bieżącym pliku. Wybierz inny rekord.",
  "Separate Strands": "Osobne nici",
  "Sequence": "Sekwencja",
  "Sequence content is undefined: a record has no sequence after ORIGIN. Use a GenBank/DDBJ file that includes the sequence.": "Zawartość sekwencji jest niezdefiniowana: rekord nie ma sekwencji po ORIGIN. Użyj pliku GenBank/DDBJ, który zawiera sekwencję.",
  "Sequence is unavailable.": "Sekwencja jest niedostępna.",
  "Sequence {n}.": "Sekwencja {n}.",
