  "Session": "Sesja",
  "Session file: the feature list and the Legend and stroke edits of the saved diagram ({path}) could not be read and are left out.": "Plik sesji: nie udało się odczytać listy cech oraz edycji legendy i konturu zapisanego diagramu ({path}); zostały pominięte.",
  "Session file: the field {items} could not be read and was left out.": "Plik sesji: nie udało się odczytać pola {items}; pominięto je.",
  "Session file: the fields {items} could not be read and were left out.": {"few": "Plik sesji: nie udało się odczytać pól {items}; pominięto je.", "many": "Plik sesji: nie udało się odczytać pól {items}; pominięto je.", "other": "Plik sesji: nie udało się odczytać pól {items}; pominięto je."},
  "Session file: the saved Results ({path}) could not be read and are left out.": "Plik sesji: nie udało się odczytać zapisanych wyników ({path}); zostały pominięte.",
  "Session file: the saved diagram of the other mode ({path}) could not be read and is left out.": "Plik sesji: nie udało się odczytać zapisanego diagramu w drugim trybie ({path}); został pominięty.",
  "Session file: the settings of both drawings ({path}) could not be read and are left out.": "Plik sesji: nie udało się odczytać ustawień obu rysunków ({path}); zostały pominięte.",
  "Session file: the settings of the Circular drawing ({path}) could not be read and are left out.": "Plik sesji: nie udało się odczytać ustawień rysunku kolistego ({path}); zostały pominięte.",
  "Session file: the settings of the Linear drawing ({path}) could not be read and are left out.": "Plik sesji: nie udało się odczytać ustawień rysunku liniowego ({path}); zostały pominięte.",
  "Session file: the stored input files ({path}) could not be read and are left out.": "Plik sesji: nie udało się odczytać zapisanych plików wejściowych ({path}); zostały pominięte.",
  "Session file: {name} ({path}) could not be read and is left out.": "Plik sesji: nie udało się odczytać elementu {name} ({path}); pominięto go.",
  "Session loaded.": "Wczytano sesję.",
  "Session loaded: {file}": "Wczytano sesję: {file}",
  "Session not loaded": "Nie wczytano sesji",
  "Session render requests require at least one record.": "Żądania renderowania sesji wymagają co najmniej jednego rekordu.",
  "Session saved: {file}.": "Zapisano sesję: {file}.",
  "Session table: {table}.": "Tabela sesji: {table}.",
  "Session title": "Tytuł sesji",
  "Session version {version} is newer than this gbdraw supports ({latest}).": "Wersja sesji {version} jest nowsza niż najnowsza obsługiwana przez tę wersję gbdraw ({latest}).",
  "Set all adjacent comparisons": "Ustaw porównania wszystkich sąsiednich par",
  "Set circular label placement. 'Out' places labels outside; 'Both' places labels outside and inside. With horizontal inner labels, implicit GC content and GC skew tracks are hidden to avoid overlap.": "Ustawia rozmieszczenie etykiet w diagramie kolistym. „Na zewnątrz” umieszcza etykiety na zewnątrz; „Oba” umieszcza je na zewnątrz i wewnątrz. Przy poziomych etykietach wewnętrznych niejawne ścieżki zawartości GC i GC skew są ukrywane, aby uniknąć nakładania się.",
  "Set id \"{text}\" is used by another set, so it was saved as \"{stored}\".": "ID zestawu „{text}” jest używany przez inny zestaw, więc zapisano jako „{stored}”.",
  "Set id cannot be empty, so it was saved as \"{stored}\".": "ID zestawu nie może być pusty, więc zapisano jako „{stored}”.",
  "Set legend label": "Etykieta legendy zestawu",
  "Set legend label (optional)": "Etykieta legendy zestawu (opcjonalnie)",
  "Set no comparison": "Ustaw brak porównania",
  "Set pairs to No comparison": "Ustaw pary na Brak porównania",
  "Set that feature's Feature placement to Auto or Main, or use Track Layout Features on axis with Separate Strands off.": "Ustaw dla tej cechy Rozmieszczenie cechy na Automatycznie lub Główny albo użyj ustawienia Układ ścieżek: Cechy na osi, przy wyłączonym ustawieniu Osobne nici.",
  "Set that feature's Feature placement to Auto or Main, or use split feature lanes (Track Preset Middle).": "Ustaw dla tej cechy Rozmieszczenie cechy na Automatycznie lub Główny albo użyj podzielonych torów cech (ustawienie wstępne ścieżek Middle).",
  "Set the ring name, color, and default order for each pairwise comparison source. Custom Track Slots can override the radial track order.": "Ustaw nazwę pierścienia, kolor i kolejność domyślną dla każdego źródła porównania parami. Niestandardowe sloty ścieżek mogą nadpisać promieniową kolejność ścieżek.",
  "Set the translation table for each sequence in its {options}.": "Ustaw kod genetyczny każdej sekwencji w jej sekcji {options}.",
  "Set up a comparison in the Comparison panel, or choose Clear comparison, then Generate again.": "Skonfiguruj porównanie w panelu Porównanie albo wybierz Wyczyść porównanie, a potem wygeneruj ponownie.",
  "Sets the {type} default color ({type} features without their own color or rule, also hidden ones).": "Ustawia domyślny kolor cech {type} (cech {type} bez własnego koloru lub reguły, także ukrytych).",
  "Setting: {path}.": "Ustawienie: {path}.",
  "Settings": "Ustawienia",
  "Settings of the clicked element": "Ustawienia klikniętego elementu",
  "Settings sections": "Sekcje ustawień",
  "Settings: a part ({path}) could not be read and was left out, with the settings inside it.": "Ustawienia: nie udało się odczytać części ({path}); pominięto ją wraz z zawartymi w niej ustawieniami.",
