  "Settings: {count} entries of {path} could not be read and were dropped.": {"few": "Ustawienia: odrzucono {count} wpisy z {path}, których nie udało się odczytać.", "many": "Ustawienia: odrzucono {count} wpisów z {path}, których nie udało się odczytać.", "other": "Ustawienia: odrzucono {count} wpisu z {path}, którego nie udało się odczytać."},
  "Settings: {count} entry of {path} could not be read and was dropped.": "Ustawienia: odrzucono {count} wpis z {path}, którego nie udało się odczytać.",
  "Settings: {path} names a file or record this Session does not hold; it is left out.": "Ustawienia: {path} wskazuje plik lub rekord, którego ta sesja nie zawiera; pominięto go.",
  "Several candidates": "Kilku kandydatów",
  "Shaft Width Ratio": "Stosunek szerokości trzonu",
  "Shaft thickness divided by the full rendered feature thickness. Enter a value greater than 0 and at most 1: 1 keeps a full-width body, while smaller values narrow the shaft. Short arrows may render as triangles.": "Grubość trzonu podzielona przez pełną wyrenderowaną grubość cechy. Wpisz wartość większą niż 0 i nie większą niż 1: wartość 1 zachowuje korpus na pełnej szerokości, a mniejsze wartości zwężają trzon. Krótkie strzałki mogą być rysowane jako trójkąty.",
  "Shared Y-axis": "Wspólna oś Y",
