  "Show on the diagram": "Pokaż na diagramie",
  "Show only a sub-region (1-based, inclusive). For multi-record files, specify the record ID or #<number>. A region that reaches past the record end is drawn to the record end.": "Pokaż tylko podregion (liczone od 1, z obu końcami włącznie). W plikach z wieloma rekordami podaj ID rekordu lub #<number>. Region wykraczający poza koniec rekordu jest rysowany do końca rekordu.",
  "Show or hide the feature search bar": "Pokaż lub ukryj pasek wyszukiwania cech",
  "Show pair": "Pokaż parę",
  "Show pair {pair}": "Pokaż parę {pair}",
  "Show primary coordinate ticks and labels in simple mode. The circular genome axis remains visible when this is off.": "Pokazuje główne znaczniki współrzędnych i etykiety w trybie prostym. Kolista oś genomu pozostaje widoczna, gdy opcja jest wyłączona.",
  "Show stroke options": "Pokaż opcje konturu",
  "Show the GC content percent axis line. Hiding the axis also hides percent tick marks and labels.": "Pokazuje linię osi procentowej zawartości GC. Ukrycie osi ukrywa też znaczniki podziałki i etykiety procentowe.",
  "Show the bottom scale bar or ruler and any coordinate ticks and labels drawn on record axes. Main record axes remain visible when this is off.": "Pokazuje dolny pasek skali lub linijkę oraz wszystkie znaczniki współrzędnych i etykiety rysowane na osiach rekordów. Główne osie rekordów pozostają widoczne, gdy opcja jest wyłączona.",
  "Show the depth coverage axis line. Hiding the axis also hides depth tick marks and labels.": "Pokaż linię osi głębokości pokrycia. Ukrycie osi ukrywa też znaczniki podziałki i etykiety głębokości.",
  "Show the label editor": "Pokaż edytor etykiet",
