  "Show this label": "Pokaż tę etykietę",
  "Showing and hiding apply at once; leaving a feature out of protein search applies on Generate": "Pokazanie i ukrycie działają od razu; wykluczenie cechy z wyszukiwania białek stosuje się przy generowaniu",
  "Showing the last successful Result again; your changes were not applied. Correct the cause and retry.": "Ponownie pokazano ostatni pomyślny wynik; zmiany nie zostały zastosowane. Usuń przyczynę i spróbuj ponownie.",
