  "Similarity groups": "Grupy podobieństwa",
  "Similarity groups and Collinear blocks compare every adjacent pair with LOSAT, so they do not run on pairs set one by one in Selected pairs. Choose Run LOSAT for all adjacent pairs, or choose Pairwise matches.": "Grupy podobieństwa i bloki kolinearne porównują każdą sąsiednią parę przez LOSAT, więc nie działają na parach ustawionych pojedynczo w sekcji Wybrane pary. Wybierz Uruchom LOSAT dla wszystkich sąsiednich par albo Dopasowania parami.",
  "Similarity groups and Collinear blocks compare every adjacent pair with LOSAT.": "Grupy podobieństwa i bloki kolinearne porównują każdą sąsiednią parę za pomocą LOSAT.",
  "Similarity groups appear after a Linear comparison with Similarity groups turned on.": "Grupy podobieństwa pojawiają się po porównaniu w diagramie liniowym z włączonymi grupami podobieństwa.",
  "Similarity groups: {count} description edit ({path}) names a group the saved Result does not have and was dropped.": "Grupy podobieństwa: {count} edycja opisu ({path}) wskazuje grupę, której nie ma w zapisanym wyniku; odrzucono ją.",
  "Similarity groups: {count} description edits ({path}) name a group the saved Result does not have and were dropped.": {"few": "Grupy podobieństwa: {count} edycje opisu ({path}) wskazują grupę, której nie ma w zapisanym wyniku; odrzucono je.", "many": "Grupy podobieństwa: {count} edycji opisu ({path}) wskazuje grupę, której nie ma w zapisanym wyniku; odrzucono je.", "other": "Grupy podobieństwa: {count} edycji opisu ({path}) wskazuje grupę, której nie ma w zapisanym wyniku; odrzucono je."},
  "Similarity groups: {count} name edit ({path}) names a group the saved Result does not have and was dropped.": "Grupy podobieństwa: {count} edycja nazwy ({path}) wskazuje grupę, której nie ma w zapisanym wyniku; odrzucono ją.",
  "Similarity groups: {count} name edits ({path}) name a group the saved Result does not have and were dropped.": {"few": "Grupy podobieństwa: {count} edycje nazwy ({path}) wskazują grupę, której nie ma w zapisanym wyniku; odrzucono je.", "many": "Grupy podobieństwa: {count} edycji nazwy ({path}) wskazuje grupę, której nie ma w zapisanym wyniku; odrzucono je.", "other": "Grupy podobieństwa: {count} edycji nazwy ({path}) wskazuje grupę, której nie ma w zapisanym wyniku; odrzucono je."},
