  "Similarity-group member protein ID": "ID białka członka grupy podobieństwa",
  "Simple mode only. Above places features above the axis, Features on axis centers them on it, and Below places them below it. Use Reset to copy this choice into the custom stack.": "Tylko tryb prosty. Opcja Nad umieszcza cechy nad osią, opcja Cechy na osi wyśrodkowuje je na osi, a opcja Pod umieszcza je pod osią. Kliknij Resetuj, aby skopiować ten wybór do niestandardowego stosu.",
  "Simple mode only. Display a GC content track; use Reset to copy it into the custom stack.": "Tylko tryb prosty. Pokazuje ścieżkę zawartości GC; kliknij Resetuj, aby skopiować ją do niestandardowego stosu.",
  "Simple mode only. Display a GC skew track; use Reset to copy it into the custom stack.": "Tylko tryb prosty. Pokazuje ścieżkę GC skew; kliknij Resetuj, aby skopiować ją do niestandardowego stosu.",
  "Simple mode only. Display depth coverage tracks from uploaded TSV files; use Reset to copy them into the custom stack.": "Tylko tryb prosty. Pokazuje ścieżki głębokości pokrycia z przesłanych plików TSV; kliknij Resetuj, aby skopiować je do niestandardowego stosu.",
