  "Stretch the overlay from its anchor to this slot, over every slot between them (to_slot). None: the overlay's own band.": "Rozciąga nakładkę od jej kotwicy do tego slotu, obejmując każdy slot pomiędzy nimi (to_slot). Brak: własny pas nakładki.",
