  "Summary": "Podsumowanie",
  "Supply GenBank input or matching GFF3 and FASTA inputs.": "Podaj dane wejściowe GenBank albo pasujące dane wejściowe GFF3 i FASTA.",
  "Supply a comparison sequence file (FASTA, GenBank, or DDBJ) or BLAST outfmt 6/7 as required.": "Podaj plik sekwencji porównania (FASTA, GenBank lub DDBJ) albo BLAST outfmt 6/7, zależnie od potrzeby.",
