  "Tab-separated value (TSV) file of feature type and color. Feature types not listed keep the selected palette colors.": "Plik TSV (wartości rozdzielane tabulatorami) z typem cechy i kolorem. Typy cech, których nie ma na liście, zachowują kolory wybranej palety.",
