  "To reorder, drag a row by its grip, or focus the grip and press the Up or Down arrow.": "Aby zmienić kolejność, przeciągnij wiersz za uchwyt albo ustaw fokus na uchwycie i naciśnij strzałkę w górę lub w dół.",
