  "Topology and display start": "Topologia i początek wyświetlania",
  "Total threads": "Łączna liczba wątków",
  "Track ID '{id}' is used by more than one enabled row.": "ID ścieżki „{id}” jest używany przez więcej niż jeden włączony wiersz.",
  "Track Layout": "Układ ścieżek",
