  "{count} Feature visibility edits from an older Session hid every feature with the same hash, such as each copy of a duplicated record. Each now applies only to the feature that was edited, so the next Generate draws the others.": {"few": "{count} edycje widoczności cechy ze starszej sesji ukrywały każdą cechę o tym samym skrócie, na przykład każdą kopię zduplikowanego rekordu. Każda dotyczy teraz tylko edytowanej cechy, więc następne generowanie rysuje pozostałe.", "many": "{count} edycji widoczności cechy ze starszej sesji ukrywało każdą cechę o tym samym skrócie, na przykład każdą kopię zduplikowanego rekordu. Każda dotyczy teraz tylko edytowanej cechy, więc następne generowanie rysuje pozostałe.", "other": "{count} edycji widoczności cechy ze starszej sesji ukrywało każdą cechę o tym samym skrócie, na przykład każdą kopię zduplikowanego rekordu. Każda dotyczy teraz tylko edytowanej cechy, więc następne generowanie rysuje pozostałe."},
